    def setUp(self):
        self.log = AuditLog(key=_KEY)
        for record in ("a", "b", "c"):
            self.log.append(record)
        self.public_key = _public_key(_SEED_A)

    def test_fields(self):
        receipt = self.log.export_signed_verifier(_SEED_A)
